{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Does WRYDECO standard shipping include wall mounting or assembly services?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. Complimentary standard worldwide shipping covers delivery to your address and does not include wall mounting, uncrating, or installation services unless explicitly arranged in writing. Because solid wood wall mounted branch bookshelves are substantial handcrafted pieces, we recommend a two-person installation or hiring a qualified local installer."
      }
    },
    {
      "@type": "Question",
      "name": "How should a wall mounted branch bookshelf be anchored to the wall for safety?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Branch bookshelves must be securely anchored into solid wood wall studs (or masonry brick/concrete using structural wall anchors) using heavy-duty wood screws that penetrate framing by at least 1.5 to 2 inches. Never mount a heavy solid wood branch shelf into unbacked drywall using plastic hollow-wall anchors alone."
      }
    },
    {
      "@type": "Question",
      "name": "How long does it take for a handcrafted branch bookshelf to be crafted and delivered?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Estimated processing and crafting takes approximately 15 to 20 business days, followed by an estimated 3 to 5 business days in transit after dispatch, for a total estimated delivery window of 18 to 25 business days. Timelines are estimates rather than guaranteed delivery dates."
      }
    },
    {
      "@type": "Question",
      "name": "Can I modify my order or cancel if I made a mistake on size or finish?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. WRYDECO provides a 6-hour Golden Window immediately after ordering during which you can cancel your order for a 100% free refund or change size, finish, and shipping details by contacting support@wrydeco.com. Once the 6-hour window closes, production begins and orders cannot be canceled."
      }
    }
  ]
}
